// Proper display name for a room id — checks ROOM_NAME_OVERRIDE first,
// then falls back to that room's own `name` field from ROOMS (e.g.
// "Electrical", which has no override since the raw room name is already
// the right display text) — NOT the raw lowercase id itself, which a
// naive `ROOM_NAME_OVERRIDE[id] || id` fallback would otherwise show.
function roomDisplayName(roomId) {
  if (ROOM_NAME_OVERRIDE[roomId]) return ROOM_NAME_OVERRIDE[roomId];
  const r = ROOMS.find(rm => rm.id === roomId);
  return r ? r.name : roomId;
}

