// ── Meme Market (weapons room) ───────────────────────────────────────────
// Fixed mock exchange rates, set by the player (not USD-pegged like
// SWAP_ASSETS — meme coins are quoted directly in "tokens per 1 NEAR",
// matching how a real meme-coin price would be communicated). Supply sizes
// vary wildly between the three coins on purpose (mirrors real meme-coin
// tokenomics), so BLACKDRAGON's "tokens per NEAR" is far larger than the
// other two.
const MEME_COINS = [
  { id: 'BLACKDRAGON', name: 'BlackDragon', tokensPerNear: 300000000, logo: BLACKDRAGON_LOGO_IMG },
  { id: 'JAMBO', name: 'Jambo', tokensPerNear: 10000, logo: JAMBO_LOGO_IMG },
  { id: 'SHITZU', name: 'Shitzu', tokensPerNear: 3000, logo: SHITZU_LOGO_IMG },
];
const MEME_BUY_FEE_NEAR = 1; // flat fee in NEAR, charged on top of the buy amount
const MEME_MIN_BUY_NEAR = 10; // minimum NEAR-equivalent spend per buy
function memeCoin(id) { return MEME_COINS.find(c => c.id === id); }
// Convert a NEAR amount into that coin's token amount, and back.
function nearToMemeTokens(coinId, nearAmt) {
  const c = memeCoin(coinId);
  return c ? nearAmt * c.tokensPerNear : 0;
}
function memeTokensToNear(coinId, tokenAmt) {
  const c = memeCoin(coinId);
  return c && c.tokensPerNear ? tokenAmt / c.tokensPerNear : 0;
}
// The "Buy Meme Coin" mission target is randomized once per game (alongside
// every other mission, at pickRandomMissions time) — a random minimum spend
// between 10-30 NEAR, held for a random 3-6 minutes. Both numbers are fixed
// for the rest of the game once assigned, same as every other mission.
const MEME_MISSION_MIN_NEAR = 10, MEME_MISSION_MAX_NEAR = 30;
const MEME_MISSION_MIN_MINUTES = 3, MEME_MISSION_MAX_MINUTES = 6;
function randomMemeMissionTarget() {
  const targetNear = Math.round(
    (MEME_MISSION_MIN_NEAR + Math.random() * (MEME_MISSION_MAX_NEAR - MEME_MISSION_MIN_NEAR)) * 10
  ) / 10;
  const holdMinutes = Math.round(
    (MEME_MISSION_MIN_MINUTES + Math.random() * (MEME_MISSION_MAX_MINUTES - MEME_MISSION_MIN_MINUTES)) * 10
  ) / 10;
  return { targetNear, holdMinutes };
}
// Current NEAR-equivalent value of all meme-coin holdings combined, used to
// check mission progress regardless of which single coin the player bought.
function memeHoldingsValueNear(memeWallet) {
  if (!memeWallet) return 0;
  return MEME_COINS.reduce((sum, c) => sum + memeTokensToNear(c.id, memeWallet[c.id] || 0), 0);
}

// Staking Vault / Claim Vault economics. Rewards are always paid out in NEAR,
// regardless of which asset was staked — the rate below is "% of staked
// amount, converted to NEAR value, per full minute staked". NEAR itself gets
// a much higher promotional rate; every other asset shares one flat rate.
// Linear & simple on purpose (no compounding) so the numbers stay readable
// and predictable for the player.
const STAKE_APY_PER_MIN_NEAR = 0.10; // 10%/min when staking NEAR
const STAKE_APY_PER_MIN_OTHER = 0.05; // 5%/min when staking any other asset
const STAKE_FEE_NEAR = 1;   // flat fee in NEAR to open a stake
const UNSTAKE_FEE_NEAR = 1; // flat fee in NEAR to close a stake
function stakeRateFor(assetId) { return assetId === 'NEAR' ? STAKE_APY_PER_MIN_NEAR : STAKE_APY_PER_MIN_OTHER; }
// Reward accrued so far, in NEAR, for a stake of `amount` of `assetId`
// running for `elapsedMs` milliseconds. Converts the staked amount to its
// NEAR-equivalent value first (so a 5%/min BTC stake still pays out a
// sensible NEAR amount), then applies the linear per-minute rate.
function stakeRewardNear(assetId, amount, elapsedMs) {
  const asset = SWAP_ASSETS.find(a => a.id === assetId);
  if (!asset) return 0;
  const nearAsset = SWAP_ASSETS.find(a => a.id === 'NEAR');
  const principalInNear = (amount * asset.usd) / nearAsset.usd;
  const minutes = elapsedMs / 60000;
  return principalInNear * stakeRateFor(assetId) * minutes;
}

// Pick a random subset of N mission rooms for this player's personal task
// list — same idea as Among Us assigning each crewmate a different set of
// tasks. Runs once per game (component mount).
// Some missions are functionally linked — you can't usefully do one without
// the other (staking something is pointless if you can never reach the
// Claim Vault to collect the reward, and vice versa). Pairs listed here are
// always assigned or skipped together, never split.
const LINKED_MISSION_ROOMS = [['upper_eng', 'lower_eng']];

function pickRandomMissions(count) {
  // "Hold 200 NEAR" is compulsory for every crewmate — it's never part of
  // the random pool, always added on top of `count` randomly-picked
  // missions from everything else. So a player ends up with `count + 1`
  // total missions: count random ones, plus this one guaranteed.
  const compulsoryDef = MISSION_DEFS.find(m => m.room === 'wallet_balance');
  const randomDefs = MISSION_DEFS.filter(m => m.room !== 'wallet_balance');

  // Group randomDefs into "units" — a linked pair becomes one unit so it
  // shuffles and gets picked as a whole, while every other mission stays its
  // own unit.
  const linkedSet = new Set(LINKED_MISSION_ROOMS.flat());
  const units = [];
  const seenRooms = new Set();
  LINKED_MISSION_ROOMS.forEach(pairRooms => {
    const defs = pairRooms.map(r => randomDefs.find(m => m.room === r)).filter(Boolean);
    if (defs.length) { units.push(defs); pairRooms.forEach(r => seenRooms.add(r)); }
  });
  randomDefs.forEach(m => {
    if (!linkedSet.has(m.room)) units.push([m]);
  });

  for (let i = units.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [units[i], units[j]] = [units[j], units[i]];
  }

  const picked = [];
  for (const unit of units) {
    if (picked.length >= count) break;
    // Skip a unit if adding it would overshoot the target count (only
    // matters for the one linked pair, which is 2 missions wide) — keep
    // scanning for a single-mission unit that fits exactly instead, so
    // every player ends up with precisely `count` random missions, never
    // more (plus the compulsory one added below).
    if (picked.length + unit.length > count) continue;
    unit.forEach(m => picked.push(m));
  }
  if (compulsoryDef) picked.push(compulsoryDef);

  // The "Buy Meme Coin" mission (weapons room) gets a random target spend
  // (10-30 NEAR) and hold duration (3-6 min) baked in right here, once per
  // game — same lifetime as every other mission. The label is rewritten to
  // show the player exactly what their personal target is.
  return picked.map(m => {
    if (m.room === 'weapons') {
      const { targetNear, holdMinutes } = randomMemeMissionTarget();
      return {
        ...m, done: false, memeTargetNear: targetNear, memeHoldMinutes: holdMinutes,
        label: `🪙 Buy ${targetNear} NEAR of meme coin & hold ${holdMinutes} min`,
      };
    }
    return { ...m, done: false };
  });
}

